import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../app/providers.dart';

class CashScreen extends ConsumerStatefulWidget {const CashScreen({super.key});@override ConsumerState<CashScreen> createState()=>_CashScreenState();}
class _CashScreenState extends ConsumerState<CashScreen>{
 bool busy=false;final Set<String> pulled={};final opening=TextEditingController();final closing=TextEditingController();
 @override void dispose(){opening.dispose();closing.dispose();super.dispose();}
 String money(double n,String currency)=>'${n.toStringAsFixed(0)} $currency';
 Future<void> _open(String businessId)async{
  final amount=double.tryParse(opening.text.replaceAll(',','.'))??0;
  setState(()=>busy=true);
  try{await ref.read(cashRepositoryProvider).open(businessId:businessId,openingAmount:amount);try{await ref.read(syncServiceProvider).syncPending();}catch(_){};opening.clear();if(mounted){setState((){});ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Caisse ouverte.')));}}
  catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Bad state: ',''))));}
  finally{if(mounted)setState(()=>busy=false);}
 }
 Future<void> _close(String businessId,Map<String,Object?> session,Map<String,double> summary)async{
  final controller=TextEditingController(text:summary['expected']!.toStringAsFixed(0));
  final actual=await showDialog<double>(context:context,builder:ctx=>AlertDialog(title:const Text('Clôturer la caisse'),content:Column(mainAxisSize:MainAxisSize.min,children:[Text('Montant théorique : ${summary['expected']!.toStringAsFixed(0)}'),TextField(controller:controller,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Montant réellement compté'))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Annuler')),FilledButton(onPressed:()=>Navigator.pop(ctx,double.tryParse(controller.text.replaceAll(',','.'))??0),child:const Text('Clôturer'))]));
  controller.dispose();if(actual==null)return;
  setState(()=>busy=true);
  try{await ref.read(cashRepositoryProvider).close(businessId:businessId,sessionId:session['id'].toString(),closingAmount:actual);try{await ref.read(syncServiceProvider).syncPending();}catch(_){};if(mounted){setState((){});ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Caisse clôturée.')));}}
  catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Bad state: ',''))));}
  finally{if(mounted)setState(()=>busy=false);}
 }
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Gestion de caisse'),actions:[IconButton(onPressed:busy?null:()=>ref.read(syncServiceProvider).syncPending().then((_)=>setState((){})).catchError((_){}),icon:const Icon(Icons.sync))]),body:FutureBuilder<Map<String,Object?>?>(future:ref.read(businessRepositoryProvider).active(),builder:(context,businessSnap){if(businessSnap.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());final business=businessSnap.data;if(business==null)return const Center(child:Text('Créez d’abord une entreprise.'));final businessId=business['id'].toString();final currency=business['currency_code']?.toString()??'XOF';if(pulled.add(businessId)){ref.read(cashRepositoryProvider).pullCloud(businessId).then((_) {if(mounted)setState((){});}).catchError((_){});}return FutureBuilder<Map<String,Object?>?>(future:ref.read(cashRepositoryProvider).activeSession(businessId),builder:(context,sessionSnap){if(sessionSnap.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());final session=sessionSnap.data;return FutureBuilder<List<Map<String,Object?>>>(future:ref.read(cashRepositoryProvider).list(businessId),builder:(context,historySnap){final history=historySnap.data??[];return ListView(padding:const EdgeInsets.all(16),children:[
 if(session==null)Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Aucune caisse ouverte',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),const SizedBox(height:8),TextField(controller:opening,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Fond de caisse initial',prefixIcon:Icon(Icons.payments_outlined))),const SizedBox(height:12),FilledButton.icon(onPressed:busy?null:()=>_open(businessId),icon:const Icon(Icons.lock_open),label:const Text('Ouvrir la caisse'))])))
 else FutureBuilder<Map<String,double>>(future:ref.read(cashRepositoryProvider).summary(businessId,session['id'].toString()),builder:(context,summarySnap){if(summarySnap.connectionState==ConnectionState.waiting)return const Card(child:Padding(padding:EdgeInsets.all(20),child:Center(child:CircularProgressIndicator())));final summary=summarySnap.data??{};return Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[const Icon(Icons.lock_open,color:Colors.green),const SizedBox(width:8),const Expanded(child:Text('Caisse ouverte',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold))),Text(session['sync_state']=='synced'?'Synchronisée':'À synchroniser',style:const TextStyle(fontSize:11))]),const SizedBox(height:12),_row('Fond initial',summary['opening']??0,currency),_row('Ventes encaissées en espèces',summary['cash_sales']??0,currency),_row('Recouvrement de dettes',summary['cash_debt_collections']??0,currency),_row('Dépenses en espèces',-(summary['cash_expenses']??0),currency),_row('Remboursements espèces',-(summary['cash_refunds']??0),currency),const Divider(),_row('Montant théorique',summary['expected']??0,currency,emphasize:true),const SizedBox(height:12),FilledButton.icon(onPressed:busy?null:()=>_close(businessId,session,summary),icon:const Icon(Icons.lock),label:const Text('Clôturer la caisse'))])));}),
 const SizedBox(height:20),const Text('Historique des caisses',style:TextStyle(fontWeight:FontWeight.bold,fontSize:17)),const SizedBox(height:8),
 ...history.map((h)=>Card(child:ListTile(leading:Icon(h['status']=='open'?Icons.lock_open:Icons.lock_outline),title:Text(h['status']=='open'?'Session ouverte':'Session clôturée'),subtitle:Text('${h['opened_at']} · ${h['sync_state']}'),trailing:Text(money((h['closing_amount'] as num?)?.toDouble()??(h['opening_amount'] as num).toDouble(),currency))))),
 ]);});});}
 Widget _row(String label,double amount,String currency,{bool emphasize=false})=>Padding(padding:const EdgeInsets.symmetric(vertical:5),child:Row(children:[Expanded(child:Text(label,style:TextStyle(fontWeight:emphasize?FontWeight.w900:FontWeight.normal))),Text(money(amount,currency),style:TextStyle(fontWeight:emphasize?FontWeight.w900:FontWeight.w600,fontSize:emphasize?17:14))]));
}
